// Compute the viewport transformation matrix that maps normalized device
// coordinates [-1,1] to screen coordinates defined by (x, y, w, h).
// The matrix follows the classic OpenGL viewport formula:
//   | w/2   0    0   x + w/2 |
//   | 0    -h/2 0   y + h/2 |
//   | 0     0    1      0   |
//   | 0     0    0      1   |
mat<4,4> m{};
m[0][0] = w * 0.5;
m[0][3] = x + w * 0.5;
m[1][1] = -h * 0.5;          // flip Y to match screen coordinates
m[1][3] = y + h * 0.5;
m[2][2] = 1.0;
m[3][3] = 1.0;
return m;
```

